template <Device::Type kDev>
void Operator<IndexSelect, kDev, 8>::operator()(const Tensor input, const Tensor index, const int64_t dim, Tensor out) const {
  const auto device_index = out.device().index();
  const auto run = [&] {
  auto at_self = ToAtenTensor<kDev>(
      const_cast<void*>(input.data()), input_shape_, input_strides_,
      input_type_, device_index);
  auto at_index = ToAtenTensor<kDev>(
      const_cast<void*>(index.data()), index_shape_, index_strides_,
      index_type_, device_index);
  auto at_out = ToAtenTensor<kDev>(
      out.data(), out_shape_, out_strides_,
      out_type_, device_index);

    at::index_select_out(at_out, at_self, dim, at_index);
  };

  if constexpr (kDev == Device::Type::kNvidia ||
      kDev == Device::Type::kCambricon ||
      kDev == Device::Type::kAscend ||
      kDev == Device::Type::kMetax ||
      kDev == Device::Type::kMoore ||
      kDev == Device::Type::kIluvatar ||
      kDev == Device::Type::kThead ||
      kDev == Device::Type::kMars ||
      kDev == Device::Type::kHygon) {
    const typename C10<kDev>::StreamGuard stream_guard{
        C10<kDev>::GetStreamFromExternal(stream_, device_index)};
    run();
    return;
  }

  run();
}


